 renderer?.dispose();renderer?.domElement.remove();renderer=scene=camera=controls=moon=nasaModel=world=surface=sun=earth=craft=orbit=link=terrainMesh=light=surfaceLight=stars=observerMarker=surfaceSun=surfaceEarth=teachingTexture=undefined;markers=[];loaded=false;hd=false;hdLoading=false;graphicsLost=false;
