window.addEventListener("message",e=>{const f=document.querySelector("#nasa-surface-frame");if(e.origin!==location.origin||e.source!==f?.contentWindow)return;if(e.data?.type==="skyline-surface-ready")f.contentWindow.postMessage({type:"skyline-region",site},location.origin);if(e.data?.type==="skyline-surface-region"&&Number.isInteger(e.data.site)&&e.data.site>=0&&e.data.site<3&&e.data.site!==site)changeSite(e.data.site);});

$('#retry-graphics').onclick=recoverGraphics;
function openObservatory(){if(!renderer){init3D();setCamera('system',true);changeSite(site)}requestAnimationFrame(resize);}

for(const b of $$('[data-understand-jump]'))b.onclick=e=>{e.preventDefault();$('#'+b.dataset.understandJump).scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});};
$('#journey-notes').onclick=revealNotes;$('#invitation-notes').onclick=revealNotes;
$('#surface-source-button').onclick=()=>$('#sources-dialog').showModal();
for(const b of $$('[data-notice]'))b.onclick=()=>{for(const c of $$('[data-notice]')){c.classList.toggle('active',c===b);c.setAttribute('aria-pressed',String(c===b));}$('#notice-response').textContent={ridge:'A ridge rises above the surrounding ground. From a lower point, it can hide part of the sky. What happens if you move?',crater:'A crater wall makes a natural skyline. Look from near its edge, then from lower ground. How does your view change?',open:'An open horizon can reveal more sky. But the Sun and Earth still move through different parts of it. Try the time experiment next.'}[b.dataset.notice];};
window.addEventListener('message',e=>{const f=$('#nasa-surface-frame');if(e.origin===location.origin&&e.source===f?.contentWindow&&e.data?.type==='skyline-viewer-height'){const height=Number(e.data.height);if(Number.isFinite(height))f.style.height=Math.max(650,Math.min(1500,height))+'px';}});

// Appended into the main module so the guide and existing simulation share state.
let journeyStep=1,freeExploration=false;
const journeyCopy={
 student:[['Choose one investigation.','Read its question. Choose one thing to change and decide what should stay the same.'],['Predict, then try.','Write a prediction before using the model. Keep your investigation’s variable in mind; the orbit controls are a separate experiment.'],['Collect two observations.','Save the first moment, change one thing, then compare. Capture both observations to use as evidence.'],['Explain using your evidence.','Describe what you changed, what happened, and whether it supported your prediction. Download your investigation.']],
};
function setJourneyStep(step,scroll=false){journeyStep=Math.max(1,Math.min(4,step));if(journeyStep===3&&experimentMode!=='light')setExperimentMode('light');const copy=journeyCopy.student[journeyStep-1];$('#journey-role').textContent='YOUR INVESTIGATION · PREDICT, TEST, EXPLAIN';$('#journey-current-title').textContent=journeyStep+'. '+copy[0];$('#journey-current-copy').textContent=copy[1];$('#journey-continue').textContent=['Go to the activities ↗','Go to the 3D model ↗','Go to the comparison ↗','Go to my field notes ↗'][journeyStep-1];for(const b of $$('[data-learning-step]')){const n=+b.dataset.learningStep;b.classList.toggle('active',n===journeyStep);b.classList.toggle('complete',n<journeyStep);b.setAttribute('aria-current',n===journeyStep?'step':'false');}if(scroll){if(journeyStep===4){$('#fieldnotes').hidden=false;$('#discovery-invitation').hidden=true;}$('#'+['experiment','understand-simulation','understand-simulation','fieldnotes'][journeyStep-1]).scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});}}
for(const b of $$('[data-learning-step]'))b.onclick=()=>setJourneyStep(+b.dataset.learningStep,true);
$('#journey-continue').onclick=()=>setJourneyStep(journeyStep,true);
$('#prediction-station').hidden=false;
for(const b of $$('[data-lesson]'))b.onclick=()=>{freeExploration=false;setLesson(+b.dataset.lesson);observer={x:0,z:3};update();$('#activity-summary').textContent='Selected: '+lessons[lesson].title;setExperimentMode('light');setJourneyStep(2,true);};
$('#choose-free').onclick=()=>{freeExploration=true;$('#activity-summary').textContent='Selected: free orbit exploration';for(const b of $$('[data-lesson]'))b.classList.remove('active');setExperimentMode('orbit');setJourneyStep(2,true);};
$('#start-test').onclick=()=>{if(!$('#prediction').value.trim()){toast('Write what you think will happen first.');$('#prediction').focus();return;}stage(1);setExperimentMode('light');$('#scene').scrollIntoView({behavior:reduced?'instant':'smooth',block:'center'});toast('Prediction saved. Try one change in the model.');};
$('#capture-moment').onclick=()=>{$('#capture').click();setJourneyStep(3);};
$('#journey-notes').onclick=()=>setJourneyStep(4,true);
$('#invitation-notes').onclick=()=>setJourneyStep(4,true);
$('#record-discovery').onclick=()=>setJourneyStep(4,true);
// Walking belongs to the geographic viewer in Explore. Here the observer stays fixed.
$('#scene').onkeydown=previousSceneKeys;
$('#orbit-play').textContent='▶ Run spacecraft';
setJourneyStep(1);

for(const id of ["altitude","inclination","phase","time"]){const el=$("#"+id),handler=el.oninput;el.oninput=e=>{handler?.(e);setJourneyStep(id==="time"?3:2);};}
for(const id of ["orbit-play","orbit-enter","surface-enter"]){const el=$("#"+id),handler=el.onclick;el.onclick=e=>{handler?.(e);setJourneyStep(2);};}
for(const b of $$("[data-camera]")){const handler=b.onclick;b.onclick=e=>{handler?.(e);setJourneyStep(2);};}
for(const id of ["baseline","delay","compare","try-sunlight","try-shadow","try-delay"]){const el=$("#"+id),handler=el.onclick;el.onclick=e=>{handler?.(e);setJourneyStep(3);};}

function orientTeachingView(){if(!camera||!controls||view!=='surface')return;const g=conditions(site,day,observer),az=rad(focusTarget==='earth'?g.earthAz:g.sunAz),el=rad(focusTarget==='earth'?g.earthEl:g.sunEl),eye=new T.Vector3(observer.x,eyeHeight(site,observer),observer.z);transition=null;camera.position.copy(eye);controls.target.copy(eye).add(new T.Vector3(Math.sin(az)*Math.cos(el),Math.sin(el),-Math.cos(az)*Math.cos(el)).multiplyScalar(8));controls.update();}
function setExperimentMode(mode,resetCamera=true){experimentMode=mode==='orbit'?'orbit':'light';$('#understand-simulation').dataset.experimentMode=experimentMode;$('#light-experiment-panel').hidden=experimentMode!=='light';$('#orbit-experiment-panel').hidden=experimentMode!=='orbit';for(const b of $$('button[data-experiment-mode]')){const on=b.dataset.experimentMode===experimentMode;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));}if(resetCamera){if(experimentMode==='light'){orbitPlaying=false;$('#orbit-play').textContent='▶ Run spacecraft';setCamera('surface',true);orientTeachingView();}else setCamera('system',true);}if(renderer)requestAnimationFrame(resize);}
for(const b of $$('button[data-experiment-mode]'))b.onclick=()=>{setExperimentMode(b.dataset.experimentMode);setJourneyStep(2);};
function chooseTarget(target){focusTarget=target;setExperimentMode('light',false);setCamera('surface',true);$('#look-at-sun').setAttribute('aria-pressed',String(target==='sun'));$('#look-at-earth').setAttribute('aria-pressed',String(target==='earth'));orientTeachingView();}
$('#look-at-sun').onclick=()=>chooseTarget('sun');$('#look-at-earth').onclick=()=>chooseTarget('earth');
const lightTimeInput=$('#time').oninput;$('#time').oninput=e=>{if(experimentMode!=='light'||view!=='surface')setExperimentMode('light');lightTimeInput(e);orientTeachingView();};
const lightSiteChange=$('#site').onchange;$('#site').onchange=e=>{setExperimentMode('light');lightSiteChange(e);orientTeachingView();};
const lightDelay=$('#delay').onclick;$('#delay').onclick=e=>{setExperimentMode('light');lightDelay(e);orientTeachingView();};
const lightPlay=$('#time-play').onclick;$('#time-play').onclick=e=>{setExperimentMode('light');lightPlay(e);};
$('#try-sunlight').onclick=()=>{day=14;observer={x:0,z:3};changeSite(0);focusTarget='sun';setExperimentMode('light');setJourneyStep(3);};
$('#try-shadow').onclick=()=>{day=15;observer={x:0,z:3};changeSite(0);focusTarget='sun';setExperimentMode('light');setJourneyStep(3);};
const delayExample=$('#try-delay').onclick;$('#try-delay').onclick=e=>{setExperimentMode('light');delayExample(e);orientTeachingView();};
for(const b of $$('[data-camera]')){const choose=b.onclick;b.onclick=e=>{choose(e);setExperimentMode(['surface','landscape'].includes(b.dataset.camera)?'light':'orbit',false);};}
// First-person look rotates only the viewing direction, keeping the measured observer fixed.
let groundPointer=null;$('#scene').addEventListener('pointerdown',e=>{if(view==='surface')groundPointer={x:e.clientX,y:e.clientY,id:e.pointerId};});
$('#scene').addEventListener('pointermove',e=>{if(!groundPointer||groundPointer.id!==e.pointerId||view!=='surface')return;const d=controls.target.clone().sub(camera.position),s=new T.Spherical().setFromVector3(d);s.theta-=(e.clientX-groundPointer.x)*.004;s.phi=T.MathUtils.clamp(s.phi+(e.clientY-groundPointer.y)*.004,.1,Math.PI-.1);controls.target.copy(camera.position).add(new T.Vector3().setFromSpherical(s));groundPointer={x:e.clientX,y:e.clientY,id:e.pointerId};controls.update();});
for(const name of ['pointerup','pointercancel','pointerleave'])$('#scene').addEventListener(name,()=>groundPointer=null);
setExperimentMode('light');

const beforeUnifiedKeys=$("#scene").onkeydown;$("#scene").onkeydown=e=>{if(view!=="surface")return beforeUnifiedKeys?.(e);if(!controls||!camera)return;if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(e.key)){e.preventDefault();const d=controls.target.clone().sub(camera.position),s=new T.Spherical().setFromVector3(d);s.theta+=e.key==="ArrowLeft"?.08:e.key==="ArrowRight"?-.08:0;s.phi=T.MathUtils.clamp(s.phi+(e.key==="ArrowUp"?-.06:e.key==="ArrowDown"?.06:0),.1,Math.PI-.1);controls.target.copy(camera.position).add(new T.Vector3().setFromSpherical(s));controls.update();}};

window.addEventListener('message',event=>{const frame=$('#analyze-workspace-frame');if(event.origin===location.origin&&event.source===frame?.contentWindow&&event.data?.type==='skyline-analyze-ready')frame.contentWindow.postMessage({type:'skyline-analyze-visibility',active:page==='analyze'},location.origin);});
